import{_ as t,I as a,o as r,c as d,b6 as i,j as l,J as s,w as c}from"./chunks/framework.BUXTSoD9.js";const E=JSON.parse('{"title":"Desarrollo Practico: SaaS de Generacion de Imagenes con IA Moderna","description":"","frontmatter":{},"headers":[],"relativePath":"es-es/stage-2/assignments/modern-landing-page/index.md","filePath":"es-es/stage-2/assignments/modern-landing-page/index.md"}'),p={name:"es-es/stage-2/assignments/modern-landing-page/index.md"},u={style:{margin:"32px 0"}};function g(m,e,h,b,f,y){const o=a("StepBar"),n=a("ClientOnly");return r(),d("div",null,[e[0]||(e[0]=i('<h1 id="desarrollo-practico-saas-de-generacion-de-imagenes-con-ia-moderna" tabindex="-1">Desarrollo Practico: SaaS de Generacion de Imagenes con IA Moderna <a class="header-anchor" href="#desarrollo-practico-saas-de-generacion-de-imagenes-con-ia-moderna" aria-label="Permalink to “Desarrollo Practico: SaaS de Generacion de Imagenes con IA Moderna”">​</a></h1><h2 id="descripcion-general" tabindex="-1">Descripcion general <a class="header-anchor" href="#descripcion-general" aria-label="Permalink to “Descripcion general”">​</a></h2><p>Este proyecto practico te requiere trabajar con un PRD real (documento de requisitos del producto) para completar desde cero un producto SaaS de generacion de imagenes con IA que toma como referencia la experiencia de Midjourney. Experimentaras el proceso completo de analisis de requisitos, descomposicion del proyecto, desarrollo iterativo e integracion y despliegue.</p><p>Esta es la seccion de practica integral de la Etapa 2. En los capitulos anteriores, ya has aprendido por separado habilidades individuales como diseno de paginas frontend, desarrollo de interfaces backend, operaciones de base de datos e integracion de pagos. Este proyecto te exige conectar todas estas habilidades para entregar un prototipo de producto funcional.</p><h2 id="conocimientos-previos" tabindex="-1">Conocimientos previos <a class="header-anchor" href="#conocimientos-previos" aria-label="Permalink to “Conocimientos previos”">​</a></h2><p>Antes de comenzar este proyecto, ya deberias dominar lo siguiente:</p><ul><li>Diseno de paginas frontend y uso de bibliotecas de componentes (<a href="./../../frontend/ui-design/">Diseno UI</a>, <a href="./../../frontend/modern-component-library/">Biblioteca de componentes moderna</a>)</li><li>Diseno y desarrollo de interfaces backend (<a href="./../../backend/ai-interface-code/">Escritura de codigo de interfaces</a>)</li><li>Fundamentos de bases de datos y Supabase (<a href="./../../backend/database-supabase/">De la base de datos a Supabase</a>)</li><li>Integracion de pagos (<a href="./../../backend/stripe-payment/">Sistema de pagos Stripe</a>)</li><li>Flujo de trabajo de Git y despliegue (<a href="./../../backend/git-workflow/">Git y GitHub</a>, <a href="./../../backend/zeabur-deployment/">Despliegue de aplicaciones web</a>)</li></ul><h2 id="objetivos-de-aprendizaje" tabindex="-1">Objetivos de aprendizaje <a class="header-anchor" href="#objetivos-de-aprendizaje" aria-label="Permalink to “Objetivos de aprendizaje”">​</a></h2><p>Despues de completar esta practica, podras:</p><ol><li>Leer y comprender un PRD real, extrayendo una lista de tareas de desarrollo</li><li>Dividir modulos basandote en el PRD, formulando un plan de avance paso a paso</li><li>Usar IA para asistir en la construccion del esqueleto frontend y el desarrollo de interfaces backend</li><li>Verificar y optimizar iterativamente cada modulo</li><li>Completar la integracion de extremo a extremo, llevando el proyecto de &quot;funcional&quot; a &quot;entregable&quot;</li></ol><h2 id="introduccion-del-proyecto" tabindex="-1">Introduccion del proyecto <a class="header-anchor" href="#introduccion-del-proyecto" aria-label="Permalink to “Introduccion del proyecto”">​</a></h2><p>El producto que vas a construir es una plataforma SaaS moderna de generacion de imagenes con IA, que incluye tres subsistemas:</p><table tabindex="0"><thead><tr><th>Subsistema</th><th>Responsabilidad</th></tr></thead><tbody><tr><td><strong>Sitio web publico</strong></td><td>Introduccion del producto, precios, FAQ, conversion de registro</td></tr><tr><td><strong>Espacio de trabajo del usuario</strong></td><td>Entrada de Prompt, generacion de imagenes, galeria, creditos, planes, interaccion comunitaria</td></tr><tr><td><strong>Panel de administracion</strong></td><td>Gestion de usuarios, gestion de tareas, gestion de pagos, moderacion de contenido, metricas SaaS, monitoreo del sistema</td></tr></tbody></table><p>El backend necesita soportar las siguientes capacidades principales: autenticacion de usuarios, tareas de generacion de imagenes, almacenamiento de objetos OSS, creditos y pagos de planes, interaccion social de imagenes y monitoreo de datos operativos.</p><div class="tip custom-block"><p class="custom-block-title">PRD</p><p>El documento de requisitos de este proyecto esta en GitHub: <a href="https://github.com/datawhalechina/easy-vibe/blob/main/docs/es-es/stage-2/assignments/modern-landing-page/PRD.md" target="_blank" rel="noreferrer">Ver PRD</a></p></div>',15)),l("div",u,[s(n,null,{default:c(()=>[s(o,{active:0,items:[{title:"Analisis de requisitos",description:"Leer el PRD, extraer paginas, modulos, modelo de datos y limites"},{title:"Construccion del esqueleto",description:"Usar IA para generar tres esqueletos frontend (www / app / admin)"},{title:"Desarrollo iterativo",description:"Agregar interfaces, permisos, pagos y monitoreo modulo por modulo"},{title:"Integracion y despliegue",description:"Verificar de extremo a extremo, desplegar y preparar la demostracion"}]})]),_:1})]),e[1]||(e[1]=i(`<h2 id="primera-parte-analisis-de-requisitos" tabindex="-1">Primera parte: Analisis de requisitos <a class="header-anchor" href="#primera-parte-analisis-de-requisitos" aria-label="Permalink to “Primera parte: Analisis de requisitos”">​</a></h2><h3 id="_1-1-leer-el-prd" tabindex="-1">1.1 Leer el PRD <a class="header-anchor" href="#_1-1-leer-el-prd" aria-label="Permalink to “1.1 Leer el PRD”">​</a></h3><p>Abre el documento PRD y responde las siguientes preguntas clave:</p><ul><li>Cuantos puntos de entrada tiene el sistema? Que paginas cubre cada uno?</li><li>Cual es la funcionalidad principal de cada pagina?</li><li>Que modulos y tablas de base de datos incluye el backend?</li><li>Cual es el alcance del MVP? Que se incluye y que se excluye en la primera version?</li></ul><div class="warning custom-block"><p class="custom-block-title custom-block-title-default">WARNING</p><p>Si no tienes respuestas claras a las preguntas anteriores, no comiences a escribir codigo. La comprension inadecuada de los requisitos es la causa mas comun de retrabajo.</p></div><h3 id="_1-2-confirmar-la-arquitectura-del-sistema" tabindex="-1">1.2 Confirmar la arquitectura del sistema <a class="header-anchor" href="#_1-2-confirmar-la-arquitectura-del-sistema" aria-label="Permalink to “1.2 Confirmar la arquitectura del sistema”">​</a></h3><p>Segun la descripcion del PRD, organiza la arquitectura general del sistema:</p><div class="language-mermaid"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">flowchart TD</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  prd[&quot;PRD&quot;] --&gt; web[&quot;Sitio web publico&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  prd --&gt; app[&quot;Espacio de trabajo del usuario&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  prd --&gt; admin[&quot;Panel de administracion&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  app --&gt; auth[&quot;Autenticacion&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  app --&gt; gen[&quot;Tarea de generacion de imagenes&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  gen --&gt; oss[&quot;Almacenamiento de objetos OSS&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  gen --&gt; db[&quot;Base de datos&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  billing[&quot;Planes y pagos&quot;] --&gt; db</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  social[&quot;Compartir / Me gusta / Comentar / Repost&quot;] --&gt; db</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  admin --&gt; analytics[&quot;Dashboard de metricas SaaS&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  admin --&gt; observability[&quot;Monitoreo de API / DB / Provider&quot;]</span></span></code></pre></div><p>Se recomienda dibujar el diagrama de arquitectura con tus propias palabras para confirmar que tu comprension del sistema es completa.</p><h2 id="segunda-parte-construccion-del-esqueleto-del-proyecto" tabindex="-1">Segunda parte: Construccion del esqueleto del proyecto <a class="header-anchor" href="#segunda-parte-construccion-del-esqueleto-del-proyecto" aria-label="Permalink to “Segunda parte: Construccion del esqueleto del proyecto”">​</a></h2><h3 id="_2-1-generar-paginas-frontend" tabindex="-1">2.1 Generar paginas frontend <a class="header-anchor" href="#_2-1-generar-paginas-frontend" aria-label="Permalink to “2.1 Generar paginas frontend”">​</a></h3><p>Usa IA para generar primero la estructura basica y los datos ficticios de todas las paginas. El objetivo de este paso es construir la arquitectura de informacion y las rutas, sin necesidad de conectar interfaces reales.</p><p>Referencia de prompts:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Basandote en el PRD actual, ayudame a generar el esqueleto frontend de un SaaS moderno de generacion de imagenes con IA.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Requisitos:</span></span>
<span class="line"><span>1. Dividido en tres puntos de entrada: www, app, admin</span></span>
<span class="line"><span>2. El sitio web incluye: inicio, precios, FAQ</span></span>
<span class="line"><span>3. La app incluye: inicio de sesion, registro, espacio de trabajo de generacion, galeria, planes, creditos, comunidad, detalle de obras, centro personal</span></span>
<span class="line"><span>4. El panel incluye: pagina principal, gestion de usuarios, gestion de tareas, gestion de contenido, gestion de planes, ordenes de pago, configuracion operativa, metricas SaaS, monitoreo del sistema</span></span>
<span class="line"><span>5. Primero generar solo la estructura de paginas y datos ficticios, sin conectar interfaces reales</span></span>
<span class="line"><span>6. Estilo referenciado en Midjourney: simple, moderno y con sensacion de producto</span></span></code></pre></div><h3 id="_2-2-verificar-la-estructura-de-paginas" tabindex="-1">2.2 Verificar la estructura de paginas <a class="header-anchor" href="#_2-2-verificar-la-estructura-de-paginas" aria-label="Permalink to “2.2 Verificar la estructura de paginas”">​</a></h3><p>Despues de generar el esqueleto, verificar item por item:</p><ul><li>[ ] Las rutas de los tres puntos de entrada son independientes (<code>/</code>, <code>/app</code>, <code>/admin</code>)</li><li>[ ] El numero de paginas coincide con el PRD</li><li>[ ] Cada pagina es accesible y navegable</li><li>[ ] Los datos ficticios muestran estados basicos de la interfaz (listas, estados vacios, formularios, etc.)</li></ul><h2 id="tercera-parte-desarrollo-iterativo" tabindex="-1">Tercera parte: Desarrollo iterativo <a class="header-anchor" href="#tercera-parte-desarrollo-iterativo" aria-label="Permalink to “Tercera parte: Desarrollo iterativo”">​</a></h2><h3 id="_3-1-avanzar-por-modulos" tabindex="-1">3.1 Avanzar por modulos <a class="header-anchor" href="#_3-1-avanzar-por-modulos" aria-label="Permalink to “3.1 Avanzar por modulos”">​</a></h3><p>Sobre la base del esqueleto, agrega funcionalidades modulo por modulo en el siguiente orden:</p><ol><li><strong>Autenticacion</strong>: Registro, inicio de sesion, diferenciacion de roles</li><li><strong>Base de datos</strong>: Creacion de tablas, interfaces de lectura y escritura</li><li><strong>Negocio principal</strong>: Tareas de generacion de imagenes, almacenamiento de resultados</li><li><strong>Almacenamiento OSS</strong>: Carga y acceso de imagenes</li><li><strong>Pagos</strong>: Planes, creditos, integracion con Stripe</li><li><strong>Interaccion social</strong>: Compartir, me gusta, comentarios</li><li><strong>Panel de administracion</strong>: Gestion de usuarios, gestion de tareas, moderacion de contenido</li><li><strong>Monitoreo de datos</strong>: Dashboard de metricas SaaS, monitoreo del sistema</li></ol><p>Despues de completar cada modulo, usa la siguiente tabla para autoverificacion:</p><table tabindex="0"><thead><tr><th>Item de verificacion</th><th>Metodo de verificacion</th></tr></thead><tbody><tr><td>Consistencia de paginas</td><td>El numero de paginas, puntos de entrada y funcionalidades coinciden con el PRD</td></tr><tr><td>Correccion de interfaces</td><td>Los parametros de solicitud, estructura de respuesta y manejo de estados son razonables</td></tr><tr><td>Aislamiento de permisos</td><td>Los usuarios normales y administradores estan mutuamente aislados</td></tr><tr><td>Consistencia de datos</td><td>Base de datos, OSS, pagos y creditos coinciden</td></tr><tr><td>Demostrabilidad</td><td>Se puede demostrar un flujo de negocio completo a otra persona</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title custom-block-title-default">TIP</p><p>Si encuentras que el contenido generado por IA se desvia del PRD, no vuelvas a hacer toda la pagina desde cero; simplemente pidele que modifique los modulos especificos.</p></div><h3 id="_3-2-roles-y-responsabilidades" tabindex="-1">3.2 Roles y responsabilidades <a class="header-anchor" href="#_3-2-roles-y-responsabilidades" aria-label="Permalink to “3.2 Roles y responsabilidades”">​</a></h3><p>Durante la iteracion, necesitas asumir tres roles simultaneamente:</p><ul><li><strong>Gerente de producto</strong>: Confirmar que la funcionalidad de cada modulo cumple con el PRD</li><li><strong>Lider tecnico</strong>: Confirmar que la solucion de implementacion es razonable</li><li><strong>Ingeniero de pruebas</strong>: Confirmar que la funcionalidad funciona correctamente</li></ul><h2 id="cuarta-parte-integracion-y-despliegue" tabindex="-1">Cuarta parte: Integracion y despliegue <a class="header-anchor" href="#cuarta-parte-integracion-y-despliegue" aria-label="Permalink to “Cuarta parte: Integracion y despliegue”">​</a></h2><h3 id="_4-1-pruebas-de-extremo-a-extremo" tabindex="-1">4.1 Pruebas de extremo a extremo <a class="header-anchor" href="#_4-1-pruebas-de-extremo-a-extremo" aria-label="Permalink to “4.1 Pruebas de extremo a extremo”">​</a></h3><p>El enfoque de la etapa final no es agregar nuevas paginas, sino hacer que el flujo de negocio completo funcione. Verificar al menos los siguientes escenarios:</p><ul><li>Registrarse -&gt; Comprar creditos -&gt; Generar imagen -&gt; Ver historial -&gt; Compartir e interactuar</li><li>Iniciar sesion como administrador -&gt; Ver datos de usuarios -&gt; Ver estadisticas de tareas -&gt; Ver monitoreo del sistema</li></ul><h3 id="_4-2-despliegue" tabindex="-1">4.2 Despliegue <a class="header-anchor" href="#_4-2-despliegue" aria-label="Permalink to “4.2 Despliegue”">​</a></h3><p>Desplegar el proyecto en un entorno publico, asegurando:</p><ul><li>Las variables de entorno estan completamente configuradas</li><li>La URL de callback de inicio de sesion es correcta</li><li>La URL de callback de pago es correcta</li><li>Las paginas no carecen de estados de loading, estados vacios ni mensajes de error</li></ul><p>Tutorial de despliegue de referencia: <a href="./../../backend/git-workflow/">Flujo de trabajo de Git y GitHub</a>, <a href="./../../backend/zeabur-deployment/">Despliegue de aplicaciones web</a>.</p><h2 id="entregables" tabindex="-1">Entregables <a class="header-anchor" href="#entregables" aria-label="Permalink to “Entregables”">​</a></h2><p>Despues de completar este proyecto, necesitas enviar lo siguiente:</p><ul><li>[ ] Enlace de demostracion en linea accesible</li><li>[ ] Enlace al repositorio de codigo fuente (incluyendo README)</li><li>[ ] Documento PRD</li><li>[ ] Capturas de pantalla de paginas clave (inicio del sitio web, espacio de trabajo de generacion, galeria, pagina de planes, pagina principal del panel)</li><li>[ ] Video de demostracion de 60 segundos (cubriendo registro -&gt; generacion -&gt; visualizacion -&gt; panel de administracion)</li></ul><p>El README debe incluir al menos: introduccion del proyecto, descripcion de paginas principales, stack tecnologico, pasos de inicio local y lista de variables de entorno.</p><h2 id="criterios-de-evaluacion" tabindex="-1">Criterios de evaluacion <a class="header-anchor" href="#criterios-de-evaluacion" aria-label="Permalink to “Criterios de evaluacion”">​</a></h2><table tabindex="0"><thead><tr><th>Dimension</th><th>Requisitos basicos</th><th>Requisitos avanzados</th></tr></thead><tbody><tr><td>Alineacion con PRD</td><td>Paginas, funcionalidades y estructura de datos basicamente cumplen con el PRD</td><td>Puede explicar claramente la correspondencia entre cada decision de diseno y el PRD</td></tr><tr><td>Ciclo completo del producto</td><td>Registrarse -&gt; Comprar creditos -&gt; Generar imagen -&gt; Ver historial -&gt; Compartir e interactuar funciona completamente</td><td>Los estados de pago, saldo de creditos y numero de generaciones son consistentes</td></tr><tr><td>Capacidades del panel</td><td>Gestion de usuarios, tareas, pagos y contenido son consultables</td><td>El dashboard de metricas SaaS y la pagina de monitoreo del sistema son funcionales</td></tr><tr><td>Completitud de ingenieria</td><td>Frontend, backend, base de datos, OSS y pipeline de pagos conectados</td><td>Tiene manejo de errores, estados vacios y estados de loading</td></tr><tr><td>Calidad de entrega</td><td>Desplegable y ejecutable</td><td>README claro, video de demostracion con estructura completa</td></tr></tbody></table><h2 id="referencias" tabindex="-1">Referencias <a class="header-anchor" href="#referencias" aria-label="Permalink to “Referencias”">​</a></h2><ul><li><a href="./../../frontend/ui-design/">Diseno UI</a></li><li><a href="./../../frontend/multi-product-ui/">Diseno de paginas y botones con especificaciones UI</a></li><li><a href="./../../frontend/llm-skills-beautiful/">Mejorar la apariencia de la interfaz con LLM y Skills</a></li><li><a href="./../../frontend/design-to-code/">De prototipo de diseno a codigo del proyecto</a></li><li><a href="./../../frontend/modern-component-library/">Biblioteca de componentes moderna</a></li><li><a href="./../../backend/database-supabase/">De la base de datos a Supabase</a></li><li><a href="./../../backend/ai-interface-code/">Escritura de codigo de interfaces</a></li><li><a href="./../../backend/git-workflow/">Flujo de trabajo de Git y GitHub</a></li><li><a href="./../../backend/zeabur-deployment/">Despliegue de aplicaciones web</a></li><li><a href="./../../backend/stripe-payment/">Sistema de pagos Stripe</a></li></ul>`,43))])}const v=t(p,[["render",g]]);export{E as __pageData,v as default};
